INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53311, 'Jeremiah 37:5', 'Jeremiah', 37, 5, 'په هم هغه وخت کښې د فِرعون فوجيانو مِصر پرېښودو او د يهوداه خوا ته روان شول، نو کله چې د بابليانو فوجيانو چا چې يروشلم محاصره کړے وو د هغوئ د راتلو په حقله واورېدل نو هغوئ د يروشلم نه وروستو شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_5.mp3', '', 1761754199, 1761754199),
(53312, 'Jeremiah 37:6', 'Jeremiah', 37, 6, 'نو بيا په هغه وخت کښې مالِک خُدائ يرمياه نبى ته پېغام ورکړو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_6.mp3', '', 1761754199, 1761754199),
(53313, 'Jeremiah 37:7', 'Jeremiah', 37, 7, 'او وې فرمائيل چې، ”صدقياه د يهوداه بادشاه چا چې تۀ رالېږلے يې چې زما نه تپوس وکړى هغۀ ته ووايه، د مِصر فوجيان کوم چې په دې تکل راروان وُو چې ستاسو مدد وکړى هغوئ به زر خپل مُلک مِصر ته واپس لاړ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_7.mp3', '', 1761754199, 1761754199),
(53314, 'Jeremiah 37:8', 'Jeremiah', 37, 8, 'نو بابليان به واپس راوګرځى او په دې ښار باندې به حمله وکړى، هغوئ به دا ښار قبضه کړى او اور به ورته واچوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_8.mp3', '', 1761754199, 1761754199),
(53315, 'Jeremiah 37:9', 'Jeremiah', 37, 9, 'مالِک خُدائ داسې فرمائى چې، خپل ځان ته دا دوکه مۀ ورکوئ چې ګنې د بابليانو فوج ستاسو نه لاړو او بيا به نۀ راځى، ځکه چې هغوئ به بيا واپس راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_9.mp3', '', 1761754199, 1761754199),
(53316, 'Jeremiah 37:10', 'Jeremiah', 37, 10, 'تر دې چې کۀ تاسو د بابليانو ټولو لښکرو ته په جنګ کښې شکست هم ورکړئ او د هغوئ په خېمو کښې صرف هغه زخميان سړى وُو چې د جنګ نه ژوندى پاتې شوى وُو، نو هغوئ به راپاڅى او دا ښار به ټول وسوزوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_10.mp3', '', 1761754199, 1761754199),
(53317, 'Jeremiah 37:11', 'Jeremiah', 37, 11, 'کله چې د بابليانو فوجيان د مِصريانو د فوجيانو د رارسېدو په وجه د يروشلم د محاصرې نه راواپس او په شا شُو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_11.mp3', '', 1761754199, 1761754199),
(53318, 'Jeremiah 37:12', 'Jeremiah', 37, 12, 'نو يرمياه د دې دپاره د يروشلم د ښار نه د بنيامين قبائيلى علاقې ته په سفر روان شو ترڅو چې هلته کښې د خپلو خپلوانو نه زمکه کښې خپله برخه جائيداد جدا کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_12.mp3', '', 1761754199, 1761754199),
(53319, 'Jeremiah 37:13', 'Jeremiah', 37, 13, 'خو کله چې هغه د بنيامين دروازې ته ورسېدو، نو هلته د چوکيدارانو آفسر د اِرياه په نوم چې د شلمياه زوئ او د حننياه نمسے وو هغه ونيولو. او ورته يې ووئيل، ”تۀ بګوړه شوے يې او د بابليانو سره ملګرے کېږې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_13.mp3', '', 1761754199, 1761754199),
(53320, 'Jeremiah 37:14', 'Jeremiah', 37, 14, 'خو يرمياه ورته وفرمائيل چې، ”دا رښتيا نۀ دى. زۀ بګوړه نۀ يم او بابليانو سره نه ملګرے کېږم.“ خو اِرياه هغۀ ته غوږ ونۀ نيولو، او يرمياه يې ونيولو او آفسرانو ته يې پېش کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_14.mp3', '', 1761754199, 1761754199),
(53321, 'Jeremiah 37:15', 'Jeremiah', 37, 15, 'هغوئ يرمياه ته سخت غصه شول او وې وهلو او د يونتن منشى په کور کښې يې بند کړو، د کوم نه چې هغوئ جيل جوړ کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_15.mp3', '', 1761754199, 1761754199),
(53322, 'Jeremiah 37:16', 'Jeremiah', 37, 16, 'يرمياه يې په يوه تاخانه کښې بند کړو او تر ډېره وخته پورې هلته په کښې وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_16.mp3', '', 1761754199, 1761754199),
(53323, 'Jeremiah 37:17', 'Jeremiah', 37, 17, 'نو څۀ موده پس صدقياه بادشاه څوک ورولېږلو او يرمياه يې خپل محل ته راوغوښتلو، او هغۀ نه يې په راز کښې تپوس وکړو چې، ”د مالِک خُدائ د طرف نه څۀ پېغام شته څۀ؟“ يرمياه جواب ورکړو چې، ”آو، تۀ به د بابل بادشاه ته په حواله کړے شې.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_17.mp3', '', 1761754199, 1761754199),
(53324, 'Jeremiah 37:18', 'Jeremiah', 37, 18, 'نو بيا يرمياه د صدقياه بادشاه ته وفرمائيل چې، ”ما ستا يا ستا د آفسرانو او يا د دې خلقو خلاف څۀ داسې بد کړى دى چې د هغې په وجه تاسو زۀ په دې قېد کښې اچولے يم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_18.mp3', '', 1761754199, 1761754199),
(53325, 'Jeremiah 37:19', 'Jeremiah', 37, 19, 'ستاسو په هغه نبيانو باندې څۀ چل وشو چې تاسو ته به يې وئيل چې، د بابل بادشاه به نۀ په تاسو او نۀ په دې مُلک باندې حمله وکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_19.mp3', '', 1761754199, 1761754199),
(53326, 'Jeremiah 37:20', 'Jeremiah', 37, 20, 'نو اوس، بادشاه سلامته، زۀ تا ته سوال او مِنت کوم چې زما خبره واوره. ما د يونتن منشى کور ته واپس مۀ لېږه، ګنې زۀ به هلته مړ شم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_20.mp3', '', 1761754199, 1761754199),
(53327, 'Jeremiah 37:21', 'Jeremiah', 37, 21, 'نو صدقياه بادشاه حُکم وکړو چې يرمياه د يونتن منشى کور ته مۀ استوئ بلکې د هغې په ځائ يې د فوجيانو په چاوڼۍ کښې بند کړئ. او بيا بادشاه دا حکم هم وکړو چې هره ورځ ورته د تنور يوه روټۍ تر هغه وخته پورې ورکوئ ترڅو چې په ټول ښار کښې يوه روټۍ هم وى. نو يرمياه بيا د فوجيانو چاوڼۍ کښې بند کړے شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah37_verse_21.mp3', '', 1761754199, 1761754199),
(53328, 'Zephaniah 2:1', 'Zephaniah', 2, 1, 'اے بې‌شرمه قومه، يو ځائ راغونډ شئ، يو ځائ شئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_1.mp3', '', 1761754199, 1761754199),
(53329, 'Zephaniah 2:2', 'Zephaniah', 2, 2, 'د دې نه مخکښې چې مقرر وخت راشى او هغه ورځ مو لکه د بوسو په شان ورک کړى، د دې نه مخکښې چې د مالِک خُدائ سخت قهر په تاسو نازل شى، د دې نه مخکښې چې د مالِک خُدائ د غضب ورځ په تاسو راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_2.mp3', '', 1761754199, 1761754199),
(53330, 'Zephaniah 2:3', 'Zephaniah', 2, 3, 'مالِک خُدائ ولټوئ، اے د زمکې ټولو عاجزانو خلقو، تاسو چې څوک د هغۀ په احکامو عمل کوئ، صداقت ولټوئ، عاجزى ولټوئ. شايد چې تاسو د مالِک خُدائ د قهر په ورځ پټ کړے شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_3.mp3', '', 1761754199, 1761754199),
(53331, 'Zephaniah 2:4', 'Zephaniah', 2, 4, 'غزه به پرېښودلے شى او اسقلون به شاړ او ويجاړ پاتې شى. په نيمه ورځ کښې به اشدود خالى شى او عقرون به د بېخ نه وويستلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_4.mp3', '', 1761754199, 1761754199),
(53332, 'Zephaniah 2:5', 'Zephaniah', 2, 5, 'په تاسو دې افسوس وى څوک چې د سمندر په غاړ اوسېږئ، اے د چريتيانو خلقو، د مالِک خُدائ کلام ستاسو خلاف دے، اے کنعانه، د فلستيانو زمکې. زۀ به تا تباه کړم، او هيڅوک به باقى پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_5.mp3', '', 1761754199, 1761754199),
(53333, 'Zephaniah 2:6', 'Zephaniah', 2, 6, 'د سمندر غاړه به د شپونکو د څرن ځائ او د ګډو شپول وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_6.mp3', '', 1761754199, 1761754199),
(53334, 'Zephaniah 2:7', 'Zephaniah', 2, 7, 'دا به د يهوداه د پاتې شوى قوم په قبضه کښې وى، هلته به هغوئ ته د څرن ځائ مِلاو شى. په ماښام کښې به هغوئ د اسقلون په کورونو کښې څملى. مالِک خُدائ د هغوئ خُدائ پاک به د هغوئ غمخور وى، هغه به هغوئ بيا د غلامۍ نه واپس راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_7.mp3', '', 1761754199, 1761754199),
(53335, 'Zephaniah 2:8', 'Zephaniah', 2, 8, '”ما د موآب بې‌عزتى او د عمونيانو پيغورونه واورېدل، چا چې زما د خلقو بې‌عزتۍ وکړې او د هغوئ د مُلک خلاف يې دهمکيانې ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_8.mp3', '', 1761754199, 1761754199),
(53336, 'Zephaniah 2:9', 'Zephaniah', 2, 9, 'نو په دې وجه، زۀ ربُ الافواج د بنى اِسرائيلو خُدائ پاک، زۀ په خپل ذات قسم خورم، يقيناً موآب به لکه د سدوم په شان، او عمونيان به لکه د عموره په شان شى. دا ځائ به د دربو او د مالګې په کندو بدل شى، او د همېشه دپاره به شاړ ويجاړ شى. زما په خلقو کښې ژوندى پاتې به هغوئ لوټ کړى، زما د قوم ژوندى پاتې به د هغوئ مُلک قبضه کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_9.mp3', '', 1761754199, 1761754199),
(53337, 'Zephaniah 2:10', 'Zephaniah', 2, 10, 'دا هغه څۀ دى چې دوئ ته به د خپل غرور په بدله کښې او د مالِک خُدائ ربُ الافواج د قوم د بې‌عزتۍ او خندا په وجه مِلاو شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_10.mp3', '', 1761754199, 1761754199),
(53338, 'Zephaniah 2:11', 'Zephaniah', 2, 11, 'مالِک خُدائ به هغوئ ويروى کله چې هغه د ټولې دُنيا خُدايان کمزورى کړى. د دُنيا ټول قومونه به د هغۀ عبادت وکړى، او هر يو به يې په خپل مُلک کښې کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_11.mp3', '', 1761754199, 1761754199),
(53339, 'Zephaniah 2:12', 'Zephaniah', 2, 12, '”اے د ايتهوپيا خلقو، تاسو به هم زما په تُوره ووژلے شئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_12.mp3', '', 1761754199, 1761754199),
(53340, 'Zephaniah 2:13', 'Zephaniah', 2, 13, 'هغه به خپل لاس اوږد کړى د شمال خلاف او اسور به تباه کړى، نينوه به شاړ او ويجاړ کړى او لکه د صحرا په شان به يې اوچ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_13.mp3', '', 1761754199, 1761754199),
(53341, 'Zephaniah 2:14', 'Zephaniah', 2, 14, 'څاروى او رمې او هر قسمه مخلوق به هلته آرام کوى. ګونګى به د دې د ستنو په سر کښې جالې جوړې کړى. د دوئ چغې به د کړکو نه دننه راځى، ملبه به د دې په دُرشلونو کښې وى، خلق به د دې دِيار تيرونه وزغلوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_14.mp3', '', 1761754199, 1761754199),
(53342, 'Zephaniah 2:15', 'Zephaniah', 2, 15, 'دا هم هغه لاپرواه ښار دے چې په حفاظت کښې پروت وو. هغې خپل ځان سره ووئيل، ”زۀ د ټولو نه غټ يم، او زما نه علاوه بل نشته.“ هغې نه څۀ کنډر جوړ شو او د ځنګلى ځناورو جاله شوه. هر هغه څوک چې په هغې تېريږى نو ورپورې به مسخرې کوى او د يرې نه به توبې وباسى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah2_verse_15.mp3', '', 1761754199, 1761754199),
(53343, 'Leviticus 3:1', 'Leviticus', 3, 1, 'کله چې څوک د خپلې پادې یو حیوان د سلامتۍ د نذرانې په توګه د څښتن په حضور کې وړاندې کوي، هغه دې یو داسې غویی یا غوا وي چې کوم عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_1.mp3', '', 1761754199, 1761754199),
(53344, 'Leviticus 3:2', 'Leviticus', 3, 2, 'هغه به خپل لاس د حیوان په سر باندې کېږدي او هغه به د سپېڅلې خېمې د دروازې په خولې کې حلال کړي. بیا به د هارون زامن چې کاهنان دي، هغه وینه د قربانۍ د ځای په څلورو خواو باندې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_2.mp3', '', 1761754199, 1761754199),
(53345, 'Leviticus 3:3', 'Leviticus', 3, 3, 'هغه کس دې د حیوان دغه برخې څښتن ته د داسې قربانۍ په توګه چې په اور باندې تیاریږي، وړاندې کړي: ټوله وازګه چې په کولمو باندې پرته وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_3.mp3', '', 1761754199, 1761754199),
(53346, 'Leviticus 3:4', 'Leviticus', 3, 4, 'پښتورګي د هغې وازګې سره چې دپاسه ورباندې پرته وي او د اینې ډېره ښه برخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_4.mp3', '', 1761754199, 1761754199),
(53347, 'Leviticus 3:5', 'Leviticus', 3, 5, 'بیا دې کاهنان هغه ټوله د سوځېدونکې نذرانې سره د قربانۍ په ځای باندې وسوځوي. د داسې نذرانې بوی په څښتن باندې ښه لګیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_5.mp3', '', 1761754199, 1761754199),
(53348, 'Leviticus 3:6', 'Leviticus', 3, 6, 'که چېرې هغه کس د خپلې رمې څخه یو حیوان څښتن ته د سلامتۍ د نذرانې په توګه وړاندې کوي، هغه دې یو داسې ښځینه یا نر حیوان وي چې کوم عیب په کې نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_6.mp3', '', 1761754199, 1761754199),
(53349, 'Leviticus 3:7', 'Leviticus', 3, 7, 'که چېرې هغه پسه وړاندې کوي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_7.mp3', '', 1761754199, 1761754199),
(53350, 'Leviticus 3:8', 'Leviticus', 3, 8, 'نو خپل لاس دې د حیوان په سر باندې کېږدي او هغه دې د خېمې په مخکې حلال کړي. کاهنان به د هغه وینه د قربانۍ د ځای په څلورو خواو باندې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_8.mp3', '', 1761754199, 1761754199),
(53351, 'Leviticus 3:9', 'Leviticus', 3, 9, 'هغه دې د سلامتۍ د نذرانې څخه یوه داسې قرباني راوړي چې په اور باندې څښتن ته تیاریږي: لکه د هغې وازګه، ټول لم چې د ملا د هډوکي سره نژدې پرې کړل شوی وي او ټوله وازګه چې په کولمو باندې پرته وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_9.mp3', '', 1761754199, 1761754199),
(53352, 'Leviticus 3:10', 'Leviticus', 3, 10, 'پښتورګي د هغې وازګې سره چې دپاسه ورباندې پرته وي او د اینې ډېره ښه برخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_10.mp3', '', 1761754199, 1761754199),
(53353, 'Leviticus 3:11', 'Leviticus', 3, 11, 'کاهن دې هغه د خوړو د نذرانې په توګه څښتن ته د قربانۍ په ځای باندې وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_11.mp3', '', 1761754199, 1761754199),
