(53355, 'Leviticus 3:13', 'Leviticus', 3, 13, 'نو خپل لاس دې د هغه حیوان په سر باندې کېږدي او د سپېڅلې خېمې په مخکې دې حلال کړي. بیا به کاهنان د هغه وینه د قربانۍ د ځای په څلورو خواو باندې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_13.mp3', '', 1761754199, 1761754199),
(53356, 'Leviticus 3:14', 'Leviticus', 3, 14, 'هغه دې د خپلې نذرانې یوه برخه چې په اور باندې څښتن ته تیاریږي، وړاندې کړي: ټوله وازګه چې په کولمو باندې پرته وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_14.mp3', '', 1761754199, 1761754199),
(53357, 'Leviticus 3:15', 'Leviticus', 3, 15, 'پښتورګي د هغې وازګې سره چې دپاسه ورباندې پرته وي او د اینې ډېره ښه برخه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/leviticus3_verse_15.mp3', '', 1761754199, 1761754199),
