(53372, 'Deuteronomy 22:13', 'Deuteronomy', 22, 13, 'فرض کړئ یو سړی د یوې انجلۍ سره واده کوي او د هغې سره یوځای کیږي، خو وروسته یې هغه نه خوښیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_13.mp3', '', 1761754199, 1761754199),
(53373, 'Deuteronomy 22:14', 'Deuteronomy', 22, 14, 'او په هغې باندې د دروغو تور ولګوي او هغه بدنامه کړي او ووایي: ‹ما د دې انجلۍ سره واده وکړ، خو کله چې مونږ سره څملاستو، نو ماته معلومه شوه چې هغه پېغله نه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_14.mp3', '', 1761754199, 1761754199),
(53374, 'Deuteronomy 22:15', 'Deuteronomy', 22, 15, 'که چېرې داسې وشي، نو د انجلۍ مور او پلار دې د واده هغه روجایي چې په وینه باندې ککړه وي واخلي چې دا خبره ثابته کړي چې هغه پېغله وه. هغوی دې دا روجایي د ښار مشرانو ته د هغه ښار په دروازه کې وروښایي.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_15.mp3', '', 1761754199, 1761754199),
(53375, 'Deuteronomy 22:16', 'Deuteronomy', 22, 16, 'د هغې پلار به هغوی ته داسې ووایي: ما خپله لور دې سړي ته په نکاح ورکړې ده او اوس زما لور د هغه نه خوښیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_16.mp3', '', 1761754199, 1761754199),
(53376, 'Deuteronomy 22:17', 'Deuteronomy', 22, 17, 'په هغې باندې یې د دروغو تور لګولی دی او داسې وایي: ‹کله چې ما د هغې سره واده وکړ هغه پېغله نه وه. خو دا زما د لور د پېغلتوب ثبوت دی. د واده په روجایي باندې د وینې داغونه وګورئ!›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_17.mp3', '', 1761754199, 1761754199),
(53377, 'Deuteronomy 22:18', 'Deuteronomy', 22, 18, 'بیا دې د ښار مشران د هغې مېړه په قمچینه باندې ووهي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_18.mp3', '', 1761754199, 1761754199),
(53378, 'Deuteronomy 22:19', 'Deuteronomy', 22, 19, 'هغوی دې هغه سړی سل مثقاله سپین زر جریمه هم کړي او هغه دې د ښځې پلار ته ورکړي، ځکه چې هغه یوه اسراییلۍ ښځه بدنامه کړې ده. له دې سره سره به هغه د هغه سړي ښځه پاتې شي او ترڅو پورې چې هغه ژوندی وي، هغې ته طلاق نه شي ورکولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_19.mp3', '', 1761754199, 1761754199),
(53379, 'Deuteronomy 22:20', 'Deuteronomy', 22, 20, 'خو که چېرې دا تور حقیقت ولري او د هغې د پېغلتوب هېڅ ثبوت نه وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_20.mp3', '', 1761754199, 1761754199),
(53380, 'Deuteronomy 22:21', 'Deuteronomy', 22, 21, 'بیا دې هغوی هغه ښځه د خپل پلار د کور د دروازې خولې ته وباسي او د هغه ښار خلک دې هغه هلته سنګساره کړي چې مړه شي، ځکه چې هغې په داسې حال کې چې لا د خپل پلار په کور کې اوسېدله د واده څخه مخکې د کوم سړي سره د زنا کولو په سبب زمونږ د قوم په منځ کې له شرمه ډک کار کړی دی. نو د هغې په وژلو سره باید تاسو خپل ځانونه د دې بدکارۍ څخه خلاص کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_21.mp3', '', 1761754199, 1761754199),
(53381, 'Deuteronomy 22:22', 'Deuteronomy', 22, 22, 'که چېرې یو سړی د بل سړي د ښځې سره د زنا کولو په حال کې ونیول شي، هغوی دواړه دې ووژل شي. په دې ډول به تاسو د دې بدکارۍ څخه خلاص شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_22.mp3', '', 1761754199, 1761754199),
(53382, 'Deuteronomy 22:23', 'Deuteronomy', 22, 23, 'فرض کړئ په یو ښار کې یو سړی د یوې داسې پېغلې سره د زنا کولو په حال کې نیول کیږي چې د بل چا سره یې کوژدن شوې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_23.mp3', '', 1761754199, 1761754199),
(53383, 'Deuteronomy 22:24', 'Deuteronomy', 22, 24, 'تاسو باید هغوی دواړه د ښار څخه دباندې وباسئ او سنګسار یې کړئ چې مړه شي. هغه پېغله دې ځکه مړه شي چې د مرستې دپاره یې چیغې نه دي وهلې، که څه هم هغه په ښار کې وه او کېدای شو چې هلته د هغې چیغې اورېدل شوې وای او سړی دې ځکه مړ شي چې هغه د هغه چا سره زنا کړې ده چې کوژدن شوې وه. تاسو باید خپل ځانونه د دې بدکارۍ څخه خلاص کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy22_verse_24.mp3', '', 1761754199, 1761754199),
